  function draftRowCount(){try{const key=`ecofood-form-autosave-v1:${platform.user?.email||'guest'}:${platform.editId||'new'}`,saved=JSON.parse(localStorage.getItem(key)||'null'),keys=Object.keys(saved?.values||{}),indexes=keys.map(value=>value.match(/^entry_(\d+)_type$/)?.[1]).filter(value=>value!==undefined).map(Number);return indexes.length?Math.max(...indexes)+1:1}catch{return 1}}
  function currentContext(){const report=platform.editId&&state.reports.find(item=>item.id===platform.editId),operator=platform.user?.role==='Operator',organizations=operator?platform.organizations.filter(item=>item.name===platform.user.org):platform.organizations.filter(item=>item.active!==false),selectedOrg=report?.org||platform.formOrg||platform.user?.org||organizations[0]?.name||'',org=platform.organizations.find(item=>item.name===selectedOrg),template=platform.templates.find(item=>item.id===org?.template)||platform.templates[0],sources=platform.locations.filter(item=>item.org===selectedOrg&&item.active!==false).map(item=>item.name),types=(template?.types||[]).filter(name=>platform.wasteTypes.find(item=>item.name===name)?.active!==false);return{report,operator,organizations,selectedOrg,org,template,sources,types}}
  function blankEntry(context,index=0){const type=context.types[0]||'',meta=wasteMeta(type);return{id:`NEW-${index}`,date:today(),type,quantity:'',unit:meta.unit,disposal:meta.disposalDefault,source:context.sources[0]||'',reason:'unknown',price:0,notes:'',photo:''}}
